/** A QR code generated on the server (see lib/qr), with a label for screen readers. `className` sets its size. */
export function Qr({ svg, label, className = "size-44" }: { svg: string; label: string; className?: string }) {
  return (
    <div
      role="img"
      aria-label={label}
      className={`overflow-hidden rounded-lg border border-line bg-white p-2 [&>svg]:size-full ${className}`}
      // Generated by the qrcode library from our own URL.
      dangerouslySetInnerHTML={{ __html: svg }}
    />
  );
}
